// IFC schema knowledge (class names, predefined types, attributes, standard property sets, data types, partOf
// relations). The tables are generated by scripts/build-ifc-data.mjs from the buildingSMART IDS-Audit-tool
// sources (MIT) and loaded lazily, one chunk per IFC version.
import { ALL_ATTRIBUTES, DATA_TYPES } from './ifc-data/common.generated.ts';

export type IfcVersion = 'IFC2X3' | 'IFC4' | 'IFC4X3_ADD2';

/** Shape of the generated per-version tables. */
export interface RawSchema {
  /** [name, parent, 'A' abstract | 'C' concrete | 'E' enumeration, predefined types or enumeration values] */
  classes: [string, string, string, string[]][];
  /** [attribute name, XSD value types or null, upper-case classes that carry it] */
  attributes: [string, string[] | null, string[]][];
  /** [name, applicable classes, [[property, 's' single|'e' enumeration|'l' list|'t' table, data type | values | [t1,t2]]]] */
  psets: [string, string[], [string, string, string | string[]][]][];
  /** [occurrence class, type classes] */
  relTypes: [string, string[]][];
  /** [relation, owner class, part class] */
  partOf: [string, string, string][];
}

export interface ClassData {
  name: string;
  upper: string;
  parentUpper?: string;
  kind: 'abstract' | 'concrete' | 'enumeration';
  predefinedTypes: string[];
  /** Upper-case type classes for occurrences (IfcWall -> IFCWALLTYPE and its concrete subclasses). */
  typeClasses: string[];
}
export interface PropData {
  name: string;
  kind: 's' | 'e' | 'l' | 't';
  dataTypes: string[];
  enumeration?: string[];
}
export interface PsetData {
  name: string;
  applicable: string[];
  props: PropData[];
}
export interface PartOfRel {
  relation: string;
  owner: string;
  part: string;
}
export interface SchemaData {
  version: IfcVersion;
  /** Label used in messages: IFC2X3, IFC4, IFC4X3. */
  label: string;
  classes: Map<string, ClassData>;
  children: Map<string, string[]>;
  /** Every property set entry, including repeated names (the tool lists them all). */
  psets: PsetData[];
  /** First entry per name. */
  psetByName: Map<string, PsetData>;
  /** Attributes the tool can value-check: name to XSD types (null when the attribute holds an entity). */
  attributes: Map<string, { xsdTypes: string[] | null; classes: string[] }>;
  /** All attribute names valid in this version (includes entity-valued ones). */
  allAttributeNames: string[];
  dataTypeNames: string[];
  partOf: PartOfRel[];
  /** The class (if concrete) and all its descendants that are concrete. */
  concrete(upperName: string): string[];
  isA(upperName: string, ancestorUpper: string): boolean;
}

const BIT: Record<IfcVersion, number> = { IFC2X3: 1, IFC4: 2, IFC4X3_ADD2: 4 };

/** Every data type known to any version (the tool resolves a data type name against all of them). */
export const DATA_TYPE_BACKING = new Map<string, string | null>(DATA_TYPES.map(([n, , b]) => [n, b]));

const cache = new Map<IfcVersion, Promise<SchemaData>>();
export function loadSchema(v: IfcVersion): Promise<SchemaData> {
  let p = cache.get(v);
  if (!p) {
    p = load(v).then(build(v));
    cache.set(v, p);
  }
  return p;
}

async function load(v: IfcVersion): Promise<RawSchema> {
  switch (v) {
    case 'IFC2X3': return (await import('./ifc-data/schema-ifc2x3.generated.ts')).default;
    case 'IFC4': return (await import('./ifc-data/schema-ifc4.generated.ts')).default;
    case 'IFC4X3_ADD2': return (await import('./ifc-data/schema-ifc4x3_add2.generated.ts')).default;
  }
}

const build = (v: IfcVersion) => (raw: RawSchema): SchemaData => {
  const classes = new Map<string, ClassData>();
  for (const [name, parent, t, extra] of raw.classes) {
    const upper = name.toUpperCase();
    classes.set(upper, {
      name,
      upper,
      parentUpper: parent ? parent.toUpperCase() : undefined,
      kind: t === 'C' ? 'concrete' : t === 'A' ? 'abstract' : 'enumeration',
      predefinedTypes: t === 'E' ? [] : extra,
      typeClasses: [],
    });
  }
  const children = new Map<string, string[]>();
  for (const c of classes.values()) {
    if (c.parentUpper) {
      const l = children.get(c.parentUpper) ?? [];
      l.push(c.upper);
      children.set(c.parentUpper, l);
    }
  }
  const concreteCache = new Map<string, string[]>();
  const concrete = (u: string): string[] => {
    const hit = concreteCache.get(u);
    if (hit) return hit;
    const out: string[] = [];
    const walk = (cur: string) => {
      const c = classes.get(cur);
      if (!c) return;
      if (c.kind === 'concrete') out.push(cur);
      for (const ch of children.get(cur) ?? []) walk(ch);
    };
    walk(u);
    concreteCache.set(u, out);
    return out;
  };
  // AddRelationType: the type class (when concrete) and the concrete direct subclasses of it
  for (const [occ, types] of raw.relTypes) {
    const o = classes.get(occ.toUpperCase());
    if (!o) continue;
    const found: string[] = [];
    for (const t of types) {
      const tc = classes.get(t.toUpperCase());
      if (!tc) continue;
      if (tc.kind === 'concrete') found.push(t.toUpperCase());
      for (const ch of children.get(tc.upper) ?? []) if (classes.get(ch)?.kind === 'concrete') found.push(ch);
    }
    if (found.length) o.typeClasses.push(...found);
  }
  const psets: PsetData[] = raw.psets.map(([name, applicable, props]) => ({
    name,
    applicable,
    props: props.map(([pn, kind, x]) => ({
      name: pn,
      kind: kind as PropData['kind'],
      enumeration: kind === 'e' ? (x as string[]) : undefined,
      // data types the tool derives for the property: enumerations are stored as labels
      dataTypes: kind === 'e' ? ['IFCLABEL'] : kind === 't' ? (x as string[]).map((d) => d.toUpperCase()) : [(x as string).toUpperCase()],
    })),
  }));
  const psetByName = new Map<string, PsetData>();
  for (const p of psets) if (!psetByName.has(p.name)) psetByName.set(p.name, p);
  const attributes = new Map<string, { xsdTypes: string[] | null; classes: string[] }>();
  for (const [n, t, cls] of raw.attributes) attributes.set(n, { xsdTypes: t, classes: cls });
  const bit = BIT[v];
  return {
    version: v,
    label: v === 'IFC4X3_ADD2' ? 'IFC4X3' : v,
    classes,
    children,
    psets,
    psetByName,
    attributes,
    allAttributeNames: ALL_ATTRIBUTES.filter(([, b]) => (b & bit) === bit).map(([n]) => n),
    dataTypeNames: DATA_TYPES.filter(([, b]) => (b & bit) === bit).map(([n]) => n),
    partOf: raw.partOf.map(([relation, owner, part]) => ({ relation, owner, part })),
    concrete,
    isA(u, anc) {
      for (let cur: string | undefined = u; cur; cur = classes.get(cur)?.parentUpper) if (cur === anc) return true;
      return false;
    },
  };
};
